var BULAN_ID=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
var BULAN_MAP={januari:0,februari:1,maret:2,april:3,mei:4,juni:5,juli:6,agustus:7,september:8,oktober:9,november:10,desember:11};
var TEMA_TYPES=['vc','2shoot','mg'];

function tipeClass(t){if(t==='teater')return'theater';if(t==='2shoot')return'two-shoot';return t;}
function tipeLabel(t){var m={theater:'Theater',teater:'Theater',event:'Event',digital:'Digital',concert:'Concert',offair:'Off Air Event',vc:'VC','2shoot':'2Shoot',mg:'M&G'};return m[t]||t;}
function isTemaType(t){return TEMA_TYPES.indexOf(t)!==-1;}
function toIDDate(s){var p=s.split('-');return parseInt(p[2],10)+' '+BULAN_ID[parseInt(p[1],10)-1]+' '+p[0];}
function fromIDDate(s){var M={januari:'01',februari:'02',maret:'03',april:'04',mei:'05',juni:'06',juli:'07',agustus:'08',september:'09',oktober:'10',november:'11',desember:'12'};var p=s.toLowerCase().replace(/[^a-z0-9\s]/g,'').trim().split(/\s+/);if(p.length<3)return'';return p[2]+'-'+(M[p[1]]||'01')+'-'+p[0].padStart(2,'0');}
function extractTime(s){return(s||'').split(' ')[0];}
function parseIDDate(s){var p=s.toLowerCase().replace(/[^a-z0-9\s]/g,'').trim().split(/\s+/);if(p.length<3)return 0;var d=parseInt(p[0],10),m=BULAN_MAP[p[1]],y=parseInt(p[2],10);if(isNaN(d)||isNaN(m)||isNaN(y))return 0;return new Date(y,m,d).getTime();}
function isFuture(s){var t=parseIDDate(s);if(!t)return false;return t>=new Date(new Date().setHours(0,0,0,0)).getTime();}

/* ===== NAVIGASI ===== */
function showDashboard(){
  document.getElementById('loginGate').style.display='none';
  document.getElementById('dashboardScreen').style.display='block';
  document.querySelectorAll('.section-screen').forEach(function(el){el.style.display='none';});
  refreshAll();
}
function openSection(section){
  document.getElementById('dashboardScreen').style.display='none';
  var map={jadwal:'sectionJadwal',galeri:'sectionGaleri',hashtag:'sectionHashtag',artikel:'sectionArtikel',quiz:'sectionQuiz'};
  var el=document.getElementById(map[section]);
  if(el)el.style.display='block';
}
function goToDashboard(){
  document.querySelectorAll('.section-screen').forEach(function(el){el.style.display='none';});
  document.getElementById('dashboardScreen').style.display='block';
  updateDashboardCounts();
}
function updateDashboardCounts(){
  document.getElementById('dashJadwalTotal').textContent=jadwalData.length;
  document.getElementById('dashJadwalUpcoming').textContent=jadwalData.filter(function(r){return isFuture(r.tanggal);}).length;
  document.getElementById('dashGaleriTotal').textContent=galeriData.length;
  var al={};galeriData.forEach(function(r){al[r.folder+'|'+r.album]=1;});
  document.getElementById('dashGaleriAlbums').textContent=Object.keys(al).length;
  document.getElementById('dashHashtagTotal').textContent=hashtagData.length;
  document.getElementById('dashHashtagDesc').textContent=hashtagData.filter(function(r){return r.keterangan;}).length;
  document.getElementById('dashArtikelTotal').textContent=artikelData.length;
  var now=new Date(),bm=0;
  artikelData.forEach(function(r){var dt=parseIDDate(r.tanggal);if(dt){var dd=new Date(dt);if(dd.getMonth()===now.getMonth()&&dd.getFullYear()===now.getFullYear())bm++;}});
  document.getElementById('dashArtikelMonth').textContent=bm;
  if(document.getElementById('dashQuizTotal'))document.getElementById('dashQuizTotal').textContent=quizData.length;
}

/* ===== LOGIN ===== */
var eyeBtn=document.getElementById('loginEye'),passInput=document.getElementById('loginPass');
eyeBtn.addEventListener('click',function(){var h=passInput.type==='password';passInput.type=h?'text':'password';eyeBtn.classList.toggle('active',h);});
document.getElementById('loginBtn').addEventListener('click',doLogin);
document.getElementById('loginPass').addEventListener('keydown',function(e){if(e.key==='Enter')doLogin();});
function doLogin(){if(passInput.value===ADMIN_PASSWORD){sessionStorage.setItem('la_auth','1');showDashboard();}else{document.getElementById('loginError').textContent='Password salah!';}}
function logout(){sessionStorage.removeItem('la_auth');document.getElementById('dashboardScreen').style.display='none';document.querySelectorAll('.section-screen').forEach(function(el){el.style.display='none';});document.getElementById('loginGate').style.display='flex';passInput.value='';passInput.type='password';eyeBtn.classList.remove('active');document.getElementById('loginError').textContent='';}
if(sessionStorage.getItem('la_auth')==='1'){showDashboard();}

function apiGet(a){return fetch(API_URL+'?action='+a+'&t='+Date.now(),{redirect:'follow'}).then(function(r){return r.json();});}
function apiPost(d){return fetch(API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(d),redirect:'follow'}).then(function(r){if(!r.ok)throw new Error('err');return r.json();}).catch(function(e){console.warn('POST err:',e);return{success:true,fake:true};});}
function refreshAll(){refreshJadwal();refreshGaleri();refreshHashtag();refreshArtikel();refreshQuiz();}

/* ===== UPLOAD FOTO ===== */
function compressImageFile(file,maxW,quality){return new Promise(function(resolve,reject){var reader=new FileReader();reader.onload=function(ev){var img=new Image();img.onload=function(){var canvas=document.createElement('canvas');var w=img.width,h=img.height;if(w>maxW){h=Math.round(h*maxW/w);w=maxW;}canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',quality));};img.onerror=reject;img.src=ev.target.result;};reader.onerror=reject;reader.readAsDataURL(file);});}
function buildUploadPlaceholderHTML(px){return '<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg><p>Pilih atau seret foto ke sini</p><div class="upload-btns"><button type="button" class="btn-sm" onclick="triggerUpload(event,\''+px+'FotoGallery\')"><svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="12" cy="12" r="3"/></svg> Gallery</button><button type="button" class="btn-sm" onclick="triggerUpload(event,\''+px+'FotoFolder\')"><svg viewBox="0 0 24 24"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg> Folder</button></div><div class="upload-hint">JPG, PNG, WebP</div>';}
function handleFotoUpload(input,mode){var file=input.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Ukuran foto terlalu besar (maks 5MB)','error');input.value='';return;}var px=mode==='add'?'a':'ea';var placeholder=document.getElementById(px+'Placeholder');var previewWrap=document.getElementById(px+'PreviewWrap');placeholder.innerHTML='<div class="spinner"></div>';placeholder.style.display='';previewWrap.style.display='none';compressImageFile(file,1200,0.7).then(function(b64){if(b64.length>45000){toast('Foto terlalu besar setelah kompresi','error');placeholder.innerHTML=buildUploadPlaceholderHTML(px);previewWrap.style.display='none';input.value='';return;}if(mode==='add'){artikelFotoBase64=b64;showFotoPreview('a',b64);}else{editArtikelFotoBase64=b64;showFotoPreview('ea',b64);}toast('Foto berhasil diunggah','success');}).catch(function(){toast('Gagal memproses gambar','error');placeholder.innerHTML=buildUploadPlaceholderHTML(px);});input.value='';}
function showFotoPreview(px,src){document.getElementById(px+'FotoImg').src=src;document.getElementById(px+'PreviewWrap').style.display='';document.getElementById(px+'Placeholder').style.display='none';document.getElementById(px+'UploadArea').classList.add('has-image');}
function removeFoto(e,mode){if(e)e.stopPropagation();var px=mode==='add'?'a':'ea';document.getElementById(px+'FotoImg').src='';document.getElementById(px+'PreviewWrap').style.display='none';var ph=document.getElementById(px+'Placeholder');ph.innerHTML=buildUploadPlaceholderHTML(px);ph.style.display='';document.getElementById(px+'UploadArea').classList.remove('has-image');if(mode==='add')artikelFotoBase64='';else editArtikelFotoBase64='';}
function triggerUpload(e,inputId){if(e)e.stopPropagation();document.getElementById(inputId).click();}
function triggerUploadArea(e,px){if(e.target.closest('.upload-remove')||e.target.closest('.upload-btns')||e.target.closest('button'))return;if(document.getElementById(px+'PreviewWrap').style.display!=='none')return;document.getElementById(px+'FotoGallery').click();}
function handleDragOver(e,px){e.preventDefault();e.stopPropagation();document.getElementById(px+'UploadArea').classList.add('dragover');}
function handleDragLeave(e,px){e.preventDefault();e.stopPropagation();document.getElementById(px+'UploadArea').classList.remove('dragover');}
function handleDrop(e,px){e.preventDefault();e.stopPropagation();document.getElementById(px+'UploadArea').classList.remove('dragover');var file=e.dataTransfer.files[0];if(!file||!file.type.startsWith('image/'))return;if(file.size>5*1024*1024){toast('Ukuran foto terlalu besar','error');return;}var ph=document.getElementById(px+'Placeholder');ph.innerHTML='<div class="spinner"></div>';compressImageFile(file,1200,0.7).then(function(b64){if(b64.length>45000){toast('Foto terlalu besar','error');ph.innerHTML=buildUploadPlaceholderHTML(px);return;}var mode=px==='a'?'add':'edit';if(mode==='add')artikelFotoBase64=b64;else editArtikelFotoBase64=b64;showFotoPreview(px,b64);toast('Foto berhasil diunggah','success');}).catch(function(){toast('Gagal memproses gambar','error');ph.innerHTML=buildUploadPlaceholderHTML(px);});}

/* ===== GALERI HELPERS ===== */
function getFolderGroups(sq){var groups={},search=(sq||'').toLowerCase();galeriData.forEach(function(r){var k=r.folder+'|'+r.album;if(!groups[k])groups[k]={folder:r.folder,album:r.album,label:r.label||r.album,count:0,firstSrc:r.src};groups[k].count++;if(!groups[k].firstSrc&&r.src)groups[k].firstSrc=r.src;});var result=Object.values(groups);if(search)result=result.filter(function(g){return g.label.toLowerCase().indexOf(search)!==-1||g.album.toLowerCase().indexOf(search)!==-1;});result.sort(function(a,b){if(a.folder!==b.folder)return a.folder<b.folder?-1:1;return a.label.toLowerCase().localeCompare(b.label.toLowerCase());});return result;}
function getPhotosInFolder(folder,album,sq){var search=(sq||'').toLowerCase();return galeriData.filter(function(r){if(r.folder!==folder||r.album!==album)return false;if(!search)return true;return(r.alt||'').toLowerCase().indexOf(search)!==-1||(r.src||'').toLowerCase().indexOf(search)!==-1;});}
var ddState={g:{value:'',newKey:'',isOpen:false},eg:{value:'',newKey:'',isOpen:false}};
function getAlbumItems(cat,q){var items=[],fk={};FM[cat].forEach(function(f){fk[f.key]=1;items.push({value:cat+':::'+f.key,name:f.name,type:'fm'});});galeriData.forEach(function(r){if(r.folder!==cat||fk[r.album])return;fk[r.album]=1;items.push({value:cat+':::'+r.album,name:r.label||r.album,type:'db'});});items.sort(function(a,b){return a.name.toLowerCase().localeCompare(b.name.toLowerCase());});if(q){var ql=q.toLowerCase();items=items.filter(function(i){return i.name.toLowerCase().indexOf(ql)!==-1;});}return items;}
function renderAlbumDDList(px){var catId=px==='g'?'gCat':'egCat';var cat=document.getElementById(catId).value;var list=document.getElementById(px+'AlbumList');var search=document.getElementById(px+'AlbumSearch');var q=search.value.trim();var items=getAlbumItems(cat,q);var cv=ddState[px].value;list.innerHTML='';items.forEach(function(it){var d=document.createElement('div');d.className='album-dd-item';if(it.type==='db')d.className+=' db-item';if(it.value===cv)d.className+=' selected';d.innerHTML='<span class="dd-dot"></span>'+escHtml(it.name)+(it.type==='db'?'<span class="dd-db-tag">DB</span>':'');d.dataset.value=it.value;list.appendChild(d);});if(q){var ex=items.some(function(i){return i.name.toLowerCase()===q.toLowerCase();});if(!ex){var nd=document.createElement('div');nd.className='album-dd-item new-album';nd.dataset.value='__new__';nd.dataset.newKey=q;nd.textContent='+ Buat album baru: "'+q+'"';list.appendChild(nd);}}if(!list.children.length)list.innerHTML='<div class="album-dd-empty">Tidak ditemukan</div>';}
function openAlbumDD(px){var l=document.getElementById(px+'AlbumList'),a=document.getElementById(px+'AlbumArrow'),t=document.getElementById(px+'AlbumTrigger');l.classList.add('open');a.classList.add('open');t.classList.add('dd-open');ddState[px].isOpen=true;renderAlbumDDList(px);}
function closeAlbumDD(px){var l=document.getElementById(px+'AlbumList'),a=document.getElementById(px+'AlbumArrow'),t=document.getElementById(px+'AlbumTrigger');if(l)l.classList.remove('open');if(a)a.classList.remove('open');if(t)t.classList.remove('dd-open');ddState[px].isOpen=false;}
function setupAlbumDD(px){var search=document.getElementById(px+'AlbumSearch'),arrow=document.getElementById(px+'AlbumArrow'),list=document.getElementById(px+'AlbumList');list.addEventListener('mousedown',function(e){if(e.target.closest('.album-dd-item'))e.preventDefault();});arrow.addEventListener('click',function(e){e.stopPropagation();if(ddState[px].isOpen)closeAlbumDD(px);else openAlbumDD(px);search.focus();});search.addEventListener('focus',function(){this.select();openAlbumDD(px);});search.addEventListener('input',function(){renderAlbumDDList(px);});list.addEventListener('click',function(e){var it=e.target.closest('.album-dd-item');if(!it||!it.dataset.value)return;var v=it.dataset.value;if(v==='__new__'){ddState[px].value='__new__';ddState[px].newKey=it.dataset.newKey||'';search.value=ddState[px].newKey;}else{ddState[px].value=v;ddState[px].newKey='';var f=findFolder(v);search.value=f?f.name:it.textContent.trim();}closeAlbumDD(px);onAlbumSelect(px==='g'?'add':'edit');});search.addEventListener('keydown',function(e){if(e.key==='Escape'){closeAlbumDD(px);search.blur();}if(e.key==='Enter'){e.preventDefault();var fi=list.querySelector('.album-dd-item');if(fi)fi.click();}});search.addEventListener('blur',function(){setTimeout(function(){if(!ddState[px].isOpen)return;closeAlbumDD(px);var tt=search.value.trim();if(!tt){ddState[px].value='';ddState[px].newKey='';return;}var cv=ddState[px].value;if(cv&&cv!=='__new__'){var f=findFolder(cv);if(f&&f.name===tt)return;}if(cv==='__new__'&&ddState[px].newKey===tt)return;var catId=px==='g'?'gCat':'egCat';var cat=document.getElementById(catId).value;var all=getAlbumItems(cat,'');var exact=all.find(function(i){return i.name.toLowerCase()===tt.toLowerCase();});if(exact){ddState[px].value=exact.value;ddState[px].newKey='';search.value=exact.name;}else{ddState[px].value='__new__';ddState[px].newKey=tt;}onAlbumSelect(px==='g'?'add':'edit');},150);});}
document.addEventListener('click',function(e){['g','eg'].forEach(function(p){var dd=document.getElementById(p+'AlbumDD');if(dd&&!dd.contains(e.target))closeAlbumDD(p);});});setupAlbumDD('g');setupAlbumDD('eg');
function findFolder(v){if(!v||v==='__new__')return null;return FM_LOOKUP[v]||null;}
function gIds(m){var p=m==='add'?'g':'eg';return{cat:p+'Cat',label:p+'Label',alt:p+'Alt',baseWrap:p+'BasePathWrap',baseText:p+'BasePathText',src:p+'Src',pathLabel:p+'PathLabel'};}
function setLockedField(el,v){el.value=v;}
function onCategoryChange(mode){var p=mode==='add'?'g':'eg';ddState[p].value='';ddState[p].newKey='';document.getElementById(p+'AlbumSearch').value='';closeAlbumDD(p);onAlbumSelect(mode);}
function getNextFileNumber(cat,al){var mx=0;var pf=cat==='lana'?'lana (':'lanautica (';galeriData.forEach(function(r){if(r.folder===cat&&r.album===al&&r.src){var fn=r.src.split('/').pop();if(fn.toLowerCase().startsWith(pf.toLowerCase())){var m=fn.match(/\((\d+)\)/);if(m){var n=parseInt(m[1],10);if(n>mx)mx=n;}}}});return mx+1;}
function generateFilenames(){var cat=document.getElementById('gCat').value;var s=parseInt(document.getElementById('gFileStart').value,10);var e=parseInt(document.getElementById('gFileEnd').value,10);if(isNaN(s)||isNaN(e)||s<=0||e<=0||s>e){document.getElementById('gSrc').value='';return;}var pf=cat==='lana'?'lana':'lanautica';var lines=[];for(var i=s;i<=e;i++)lines.push(pf+' ('+i+').jpg');document.getElementById('gSrc').value=lines.join('\n');}
function unlockField(el){el.classList.remove('locked','auto-filled');el.removeAttribute('readonly');el.removeAttribute('tabindex');el.style.pointerEvents='';el.style.userSelect='';el.style.webkitUserSelect='';}
function lockField(el){el.classList.add('locked','auto-filled');el.setAttribute('readonly','');el.setAttribute('tabindex','-1');el.style.pointerEvents='none';el.style.userSelect='none';el.style.webkitUserSelect='none';}
function onAlbumSelect(mode){var p=mode==='add'?'g':'eg';var id=gIds(mode);var val=ddState[p].value;var nk=ddState[p].newKey;var f=findFolder(val);var labelEl=document.getElementById(id.label),altEl=document.getElementById(id.alt);var cat=document.getElementById(id.cat).value;var ak=val!=='__new__'&&val?val.split(':::')[1]:nk;if(val==='__new__'||!val){unlockField(labelEl);unlockField(altEl);setLockedField(labelEl,nk||'');setLockedField(altEl,'');var bp='Lana/'+(nk||'')+'/';document.getElementById(id.baseWrap).style.display='';document.getElementById(id.baseText).textContent=bp;currentBasePath=bp;if(p==='g'){var nn=getNextFileNumber(cat,ak);document.getElementById('gFileStart').value=nn;document.getElementById('gFileEnd').value=nn;document.getElementById('gRangeWrap').style.display='';generateFilenames();}document.getElementById(id.pathLabel).textContent='Filename (Multi)';}else if(f){lockField(labelEl);lockField(altEl);setLockedField(labelEl,f.name);setLockedField(altEl,f.alt);if(f.dir){document.getElementById(id.baseWrap).style.display='';document.getElementById(id.baseText).textContent=f.dir;currentBasePath=f.dir;if(p==='g'){var nn=getNextFileNumber(cat,ak);document.getElementById('gFileStart').value=nn;document.getElementById('gFileEnd').value=nn;document.getElementById('gRangeWrap').style.display='';generateFilenames();}else{var nn2=getNextFileNumber(cat,ak);document.getElementById(id.src).value=(cat==='lana'?'lana':'lanautica')+' ('+nn2+').jpg';}document.getElementById(id.pathLabel).textContent='Filename (Multi)';}else{document.getElementById(id.baseWrap).style.display='none';if(p==='g')document.getElementById('gRangeWrap').style.display='none';document.getElementById(id.src).value='';document.getElementById(id.pathLabel).textContent='Path Foto';currentBasePath='';}}else{lockField(labelEl);lockField(altEl);var pts=val.split(':::');var fd=galeriData.find(function(r){return r.folder===pts[0]&&r.album===pts[1];});setLockedField(labelEl,fd?(fd.label||''):'');setLockedField(altEl,fd?(fd.alt||''):'');if(fd&&fd.src){var ls=fd.src.lastIndexOf('/');if(ls!==-1){var dd=fd.src.substring(0,ls+1);document.getElementById(id.baseWrap).style.display='';document.getElementById(id.baseText).textContent=dd;currentBasePath=dd;if(p==='g'){var nn=getNextFileNumber(cat,ak);document.getElementById('gFileStart').value=nn;document.getElementById('gFileEnd').value=nn;document.getElementById('gRangeWrap').style.display='';generateFilenames();}document.getElementById(id.pathLabel).textContent='Filename (Multi)';}else{document.getElementById(id.baseWrap).style.display='none';if(p==='g')document.getElementById('gRangeWrap').style.display='none';currentBasePath='';document.getElementById(id.src).value='';document.getElementById(id.pathLabel).textContent='Path Foto';}}else{document.getElementById(id.baseWrap).style.display='none';if(p==='g')document.getElementById('gRangeWrap').style.display='none';document.getElementById(id.src).value='';currentBasePath='';document.getElementById(id.pathLabel).textContent='Path Foto';}}}

/* ===== NAMA DROPDOWN ===== */
var namaDDState={f:{value:'',isOpen:false},e:{value:'',isOpen:false}};
function getNamaItems(q){var items=[],nk={};jadwalData.forEach(function(r){if(nk[r.nama])return;nk[r.nama]=1;items.push({value:r.nama,name:r.nama,type:'db'});});items.sort(function(a,b){return a.name.toLowerCase().localeCompare(b.name.toLowerCase());});if(q){var ql=q.toLowerCase();items=items.filter(function(i){return i.name.toLowerCase().indexOf(ql)!==-1;});}return items;}
function renderNamaDDList(px){var list=document.getElementById(px+'NamaList');var search=document.getElementById(px+'NamaSearch');var q=search.value.trim();var items=getNamaItems(q);var cv=namaDDState[px].value;list.innerHTML='';items.forEach(function(it){var d=document.createElement('div');d.className='album-dd-item db-item';if(it.value===cv)d.className+=' selected';d.innerHTML='<span class="dd-dot"></span>'+escHtml(it.name)+'<span class="dd-db-tag">DB</span>';d.dataset.value=it.value;list.appendChild(d);});if(q){var ex=items.some(function(i){return i.name.toLowerCase()===q.toLowerCase();});if(!ex){var nd=document.createElement('div');nd.className='album-dd-item new-album';nd.dataset.value='__new__';nd.dataset.newKey=q;nd.textContent='+ Buat baru: "'+q+'"';list.appendChild(nd);}}if(!list.children.length)list.innerHTML='<div class="album-dd-empty">Ketik untuk tambah baru</div>';}
function openNamaDD(px){var l=document.getElementById(px+'NamaList'),a=document.getElementById(px+'NamaArrow'),t=document.getElementById(px+'NamaTrigger');l.classList.add('open');a.classList.add('open');t.classList.add('dd-open');namaDDState[px].isOpen=true;renderNamaDDList(px);}
function closeNamaDD(px){var l=document.getElementById(px+'NamaList'),a=document.getElementById(px+'NamaArrow'),t=document.getElementById(px+'NamaTrigger');if(l)l.classList.remove('open');if(a)a.classList.remove('open');if(t)t.classList.remove('dd-open');namaDDState[px].isOpen=false;}
function setupNamaDD(px){var search=document.getElementById(px+'NamaSearch'),arrow=document.getElementById(px+'NamaArrow'),list=document.getElementById(px+'NamaList');list.addEventListener('mousedown',function(e){if(e.target.closest('.album-dd-item'))e.preventDefault();});arrow.addEventListener('click',function(e){e.stopPropagation();if(namaDDState[px].isOpen)closeNamaDD(px);else openNamaDD(px);search.focus();});search.addEventListener('focus',function(){this.select();openNamaDD(px);});search.addEventListener('input',function(){renderNamaDDList(px);});list.addEventListener('click',function(e){var it=e.target.closest('.album-dd-item');if(!it||!it.dataset.value)return;var v=it.dataset.value;if(v==='__new__'){namaDDState[px].value='__new__';search.value=it.dataset.newKey||'';}else{namaDDState[px].value=v;search.value=v;}closeNamaDD(px);});search.addEventListener('keydown',function(e){if(e.key==='Escape'){closeNamaDD(px);search.blur();}if(e.key==='Enter'){e.preventDefault();var fi=list.querySelector('.album-dd-item');if(fi)fi.click();}});search.addEventListener('blur',function(){setTimeout(function(){if(!namaDDState[px].isOpen)return;closeNamaDD(px);var tt=search.value.trim();if(!tt){namaDDState[px].value='';return;}namaDDState[px].value=tt;},150);});}
document.addEventListener('click',function(e){['f','e'].forEach(function(p){var dd=document.getElementById(p+'NamaDD');if(dd&&!dd.contains(e.target))closeNamaDD(p);});});setupNamaDD('f');setupNamaDD('e');

/* ===== FORM JADWAL HELPERS ===== */
function updateJadwalFormUI(px){var tipe=document.getElementById(px+'Tipe').value;var tgl=document.getElementById(px+'Tanggal').value;var gJam=document.getElementById(px+'JamGroup');var gUs=document.getElementById(px+'UnitSongGroup');var gSo=document.getElementById(px+'SoGroup');var gLink=document.getElementById(px+'LinkGroup');var lbl=document.getElementById(px+'NamaLabel');var isTema=isTemaType(tipe);var isDigital=(tipe==='digital');var isPast=false;if(tgl){var today=new Date();today.setHours(0,0,0,0);var d=new Date(tgl+'T00:00:00');if(d<today)isPast=true;}if(isTema)lbl.textContent='Tema';else lbl.textContent='Nama Kegiatan';var showSoLink=isTema&&!isPast;if(gSo)gSo.style.display=showSoLink?'':'none';if(gLink)gLink.style.display=showSoLink?'':'none';if(!showSoLink){if(document.getElementById(px+'So'))document.getElementById(px+'So').value='';if(document.getElementById(px+'Link'))document.getElementById(px+'Link').value='';}if(isDigital){if(gJam)gJam.style.display='';if(gUs)gUs.style.display='none';}else if(isTema){if(gJam)gJam.style.display=isPast?'none':'';if(gUs)gUs.style.display='none';}else{if(isPast){if(gJam)gJam.style.display='none';if(gUs)gUs.style.display='';}else{if(gJam)gJam.style.display='';if(gUs)gUs.style.display='none';}}}
document.getElementById('fTipe').addEventListener('change',function(){updateJadwalFormUI('f');});
document.getElementById('fTanggal').addEventListener('change',function(){updateJadwalFormUI('f');});
document.getElementById('eTipe').addEventListener('change',function(){updateJadwalFormUI('e');});
document.getElementById('eTanggal').addEventListener('change',function(){updateJadwalFormUI('e');});

/* ===== JADWAL CRUD ===== */
function refreshJadwal(){document.getElementById('jadwalBody').innerHTML='<tr class="empty-row"><td colspan="8"><div class="spinner"></div><br>Memuat...</td></tr>';document.getElementById('jadwalFooter').innerHTML='';apiGet('read').then(function(d){jadwalData=d;renderJStats();jadwalMode='preview';jadwalPage=1;applyJadwalView();updateDashboardCounts();}).catch(function(){document.getElementById('jadwalBody').innerHTML='<tr class="empty-row"><td colspan="8" style="color:var(--red)">Gagal memuat</td></tr>';});}
function renderJStats(){var t=0,the=0,ev=0,di=0,co=0,oa=0,vc=0,ts=0,mg=0;jadwalData.forEach(function(r){t++;var tc=tipeClass(r.tipe);if(tc==='theater')the++;else if(tc==='event')ev++;else if(tc==='digital')di++;else if(tc==='concert')co++;else if(tc==='offair')oa++;else if(tc==='vc')vc++;else if(tc==='2shoot')ts++;else if(tc==='mg')mg++;});document.getElementById('statTotal').textContent=t;document.getElementById('statTheater').textContent=the;document.getElementById('statEvent').textContent=ev;document.getElementById('statDigital').textContent=di;document.getElementById('statConcert').textContent=co;document.getElementById('statOffair').textContent=oa;document.getElementById('statVc').textContent=vc;document.getElementById('stat2shoot').textContent=ts;document.getElementById('statMg').textContent=mg;}
function getSortedJadwal(){var s=(document.getElementById('searchJ').value||'').toLowerCase();var f=jadwalData.filter(function(r){return!s||r.nama.toLowerCase().indexOf(s)!==-1||r.tanggal.toLowerCase().indexOf(s)!==-1||tipeLabel(r.tipe).toLowerCase().indexOf(s)!==-1;});f.sort(function(a,b){return parseIDDate(b.tanggal)-parseIDDate(a.tanggal);});return f;}
function applyJadwalView(){var isF=jadwalMode==='full';document.getElementById('jadwalHome').classList.toggle('j-hide',isF);document.getElementById('jadwalBack').classList.toggle('j-hide',!isF);renderJadwalTable();}
function renderJadwalTable(){var f=getSortedJadwal(),isS=!!(document.getElementById('searchJ').value||'').trim();if(isS&&jadwalMode==='preview')jadwalMode='full';if(!f.length){document.getElementById('jadwalBody').innerHTML='<tr class="empty-row"><td colspan="8">'+(isS?'Tidak ditemukan':'Belum ada data')+'</td></tr>';document.getElementById('jadwalFooter').innerHTML='';return;}if(jadwalMode==='preview'){document.getElementById('jadwalBody').innerHTML=buildJRows(f.slice(0,5),1);document.getElementById('jadwalFooter').innerHTML=f.length>5?'<div class="show-more-bar"><button class="show-more-btn" onclick="enterJadwalFull()">Lihat Selengkapnya</button></div>':'';}else{var tp=Math.max(1,Math.ceil(f.length/jadwalPageSize));if(jadwalPage>tp)jadwalPage=tp;var s=(jadwalPage-1)*jadwalPageSize,e=Math.min(s+jadwalPageSize,f.length);document.getElementById('jadwalBody').innerHTML=buildJRows(f.slice(s,e),s+1);document.getElementById('jadwalFooter').innerHTML=buildPgHTML(jadwalPage,tp,f.length,s+1,e,'goJadwalPage','setJadwalPageSize',jadwalPageSize);}}
function enterJadwalFull(){jadwalMode='full';jadwalPage=1;applyJadwalView();}
function exitJadwalFull(){jadwalMode='preview';document.getElementById('searchJ').value='';applyJadwalView();}
function onJadwalSearch(){var isS=!!(document.getElementById('searchJ').value||'').trim();if(isS&&jadwalMode==='preview'){jadwalMode='full';applyJadwalView();}else renderJadwalTable();}
function goJadwalPage(p){var f=getSortedJadwal();if(p<1||p>Math.max(1,Math.ceil(f.length/jadwalPageSize)))return;jadwalPage=p;renderJadwalTable();}
function setJadwalPageSize(v){jadwalPageSize=v;jadwalPage=1;renderJadwalTable();}
function buildJRows(items,no){var h='';for(var i=0;i<items.length;i++){var r=items[i],ft=isFuture(r.tanggal),tc=tipeClass(r.tipe);var isTema=isTemaType(tc);h+='<tr><td style="color:var(--muted)">'+(no+i)+'</td><td style="font-weight:500">'+escHtml(r.nama)+'</td><td><span class="type-badge '+tc+'">'+tipeLabel(r.tipe)+'</span></td><td>'+escHtml(r.tanggal)+'</td>';var soLinkCell='<td>-</td>';if(isTema&&ft){var soHtml=r.so?'<div style="font-size:.76rem;font-weight:600;color:var(--red)">Sold Out</div>':'<div style="font-size:.68rem;font-weight:600;color:var(--green)">Tersedia</div>';var linkHtml=r.link?'<a href="'+escAttr(r.link)+'" target="_blank" class="buy-link"><svg viewBox="0 0 24 24"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg> Beli Tiket</a>':'<div style="font-size:.68rem;color:var(--muted)">-</div>';soLinkCell='<td>'+soHtml+linkHtml+'</td>';}h+=soLinkCell;var jc=ft?escHtml(r.jam):(r.unitSong||r.unit_song?'<div class="unit-song-label">'+escHtml(r.unitSong||r.unit_song).replace(/\n/g,'<br>')+'</div>':'<div class="unit-song-empty" onclick="openEditJ(\''+r.id+'\')">Unit song belum diisi</div>');h+='<td>'+jc+'</td><td><span class="status-dot '+(ft?'upcoming':'done')+'"></span>'+(ft?'Mendatang':'Selesai')+'</td><td><div class="table-actions"><button class="tbl-btn" onclick="openEditJ(\''+r.id+'\')" title="Edit"><svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="tbl-btn del" onclick="openDelete(\''+r.id+'\',\''+escAttr(r.tanggal)+'\')" title="Hapus"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button></div></td></tr>';}return h;}
function addJadwal(){var btn=document.getElementById('addJBtn');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var n=document.getElementById('fNamaSearch').value.trim(),t=document.getElementById('fTipe').value,d=document.getElementById('fTanggal').value,j=document.getElementById('fJam').value,ds=document.getElementById('fDesc').value.trim(),us=document.getElementById('fUnitSong').value.trim(),so=document.getElementById('fSo').value.trim(),lk=document.getElementById('fLink').value.trim();if(!n||!d){toast('Nama dan tanggal wajib diisi','error');btn.disabled=false;btn.textContent='Tambah';return;}apiPost({action:'add',nama:n,tipe:t,deskripsi:ds,tanggal:toIDDate(d),jam:j?j+' WIB':'',unitSong:us,so:so,link:lk}).then(function(r){if(r.success){toast('Ditambahkan','success');if(document.getElementById('quickJ').checked)document.getElementById('fTanggal').value='';else resetJForm();jadwalMode='preview';refreshJadwal();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Tambah';});}
function resetJForm(){namaDDState.f.value='';document.getElementById('fNamaSearch').value='';closeNamaDD('f');document.getElementById('fTipe').value='theater';document.getElementById('fTanggal').value='';document.getElementById('fJam').value='14:00';document.getElementById('fUnitSong').value='';document.getElementById('fDesc').value='';document.getElementById('fSo').value='';document.getElementById('fLink').value='';updateJadwalFormUI('f');}
function openEditJ(id){var r=jadwalData.find(function(x){return x.id===id;});if(!r)return;editingJId=id;namaDDState.e.value=r.nama;document.getElementById('eNamaSearch').value=r.nama;var selVal=tipeClass(r.tipe);if(selVal==='teater')selVal='theater';document.getElementById('eTipe').value=selVal;document.getElementById('eTanggal').value=fromIDDate(r.tanggal);document.getElementById('eJam').value=extractTime(r.jam);document.getElementById('eDesc').value=r.deskripsi||'';document.getElementById('eUnitSong').value=r.unitSong||r.unit_song||'';document.getElementById('eSo').value=r.so||'';document.getElementById('eLink').value=r.link||'';updateJadwalFormUI('e');openModal('editJModal');}
function saveEditJ(){var btn=document.querySelector('#editJModal .btn-save');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var n=document.getElementById('eNamaSearch').value.trim(),t=document.getElementById('eTipe').value,d=document.getElementById('eTanggal').value,j=document.getElementById('eJam').value,ds=document.getElementById('eDesc').value.trim(),us=document.getElementById('eUnitSong').value.trim(),so=document.getElementById('eSo').value.trim(),lk=document.getElementById('eLink').value.trim();if(!n||!d){toast('Nama dan tanggal wajib','error');btn.disabled=false;btn.textContent='Simpan';return;}apiPost({action:'edit',id:editingJId,nama:n,tipe:t,deskripsi:ds,tanggal:toIDDate(d),jam:j?j+' WIB':'',unitSong:us,so:so,link:lk}).then(function(r){if(r.success){toast('Diupdate','success');closeModal('editJModal');refreshJadwal();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Simpan';});}
function openDelete(id,txt){document.getElementById('deleteMsg').innerHTML='Hapus <strong style="color:var(--text)">'+escHtml(txt)+'</strong>?';var btn=document.getElementById('deleteConfirmBtn');btn.textContent='Hapus';btn.className='btn-confirm';btn.disabled=false;btn.onclick=function(){if(btn.disabled)return;btn.disabled=true;btn.textContent='Menghapus...';apiPost({action:'delete',id:id}).then(function(r){if(r.success){toast('Dihapus','success');closeModal('deleteModal');refreshJadwal();}else{toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';}}).catch(function(){toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';});};openModal('deleteModal');}

/* ===== GALERI CRUD ===== */
function refreshGaleri(){document.getElementById('galeriTableWrap').innerHTML='<div style="padding:40px;text-align:center"><div class="spinner"></div><br><span style="color:var(--muted)">Memuat...</span></div>';apiGet('readGallery').then(function(d){galeriData=d;var t=0,la=0,ln=0,al={};galeriData.forEach(function(r){t++;if(r.folder==='lana')la++;else ln++;al[r.folder+'|'+r.album]=1;});document.getElementById('gStatTotal').textContent=t;document.getElementById('gStatLana').textContent=la;document.getElementById('gStatLanautica').textContent=ln;document.getElementById('gStatAlbum').textContent=Object.keys(al).length;galeriMode='preview';galeriPage=1;galeriCurrentFolder=null;applyGaleriView();updateDashboardCounts();}).catch(function(){document.getElementById('galeriTableWrap').innerHTML='<div style="padding:40px;text-align:center;color:var(--red)">Gagal memuat</div>';});}
function applyGaleriView(){var isF=galeriMode==='full'||galeriMode==='detail';document.getElementById('galeriHome').classList.toggle('j-hide',isF);document.getElementById('galeriBack').classList.toggle('j-hide',!isF);document.getElementById('galeriDetailBar').classList.toggle('j-hide',galeriMode!=='detail');renderGaleriTable();}
function galeriGoBack(){if(galeriMode==='detail'){galeriMode='preview';galeriCurrentFolder=null;galeriPage=1;}else{galeriMode='preview';galeriPage=1;}document.getElementById('searchG').value='';applyGaleriView();}
function enterGaleriFull(){galeriMode='full';galeriPage=1;applyGaleriView();}
function enterGaleriDetail(f,a){galeriCurrentFolder={folder:f,album:a};galeriMode='detail';galeriPage=1;applyGaleriView();}
function onGaleriSearch(){galeriPage=1;var isS=!!(document.getElementById('searchG').value||'').trim();if(galeriMode==='preview'&&isS){galeriMode='full';applyGaleriView();}else renderGaleriTable();}
function renderGaleriTable(){var wrap=document.getElementById('galeriTableWrap'),footer=document.getElementById('galeriFooter'),sv=(document.getElementById('searchG').value||'').trim(),isS=!!sv;if(galeriMode==='preview'&&isS){galeriMode='full';applyGaleriView();return;}var mode=galeriMode;if(mode==='preview'||mode==='full'){var gr=getFolderGroups(sv);if(!gr.length){wrap.innerHTML='<div style="padding:40px;text-align:center;color:var(--muted)">Belum ada data</div>';footer.innerHTML='';return;}var tp=Math.max(1,Math.ceil(gr.length/galeriPageSize));if(galeriPage>tp)galeriPage=tp;var s=(galeriPage-1)*galeriPageSize,e=Math.min(s+galeriPageSize,gr.length),sh=mode==='preview'?gr.slice(0,5):gr.slice(s,e);var h='<table class="gal-table"><thead><tr><th>No</th><th>Preview</th><th>Album</th><th>Kategori</th><th>Jumlah</th><th>Aksi</th></tr></thead><tbody>';for(var i=0;i<sh.length;i++){var g=sh[i];h+='<tr class="folder-row" onclick="enterGaleriDetail(\''+escJS(g.folder)+'\',\''+escJS(g.album)+'\')">';h+='<td style="color:var(--muted)">'+(mode==='preview'?(i+1):(s+i+1))+'</td>';h+='<td>'+(g.firstSrc?'<img class="thumb-lg" src="'+escAttr(g.firstSrc)+'" onerror="this.style.display=\'none\'">':'')+'</td>';h+='<td style="font-weight:500">'+escHtml(g.label)+'</td>';h+='<td><span class="folder-badge '+g.folder+'">'+g.folder+'</span></td>';h+='<td><span style="font-weight:600;color:var(--accent2)">'+g.count+'</span></td>';h+='<td><div class="table-actions" onclick="event.stopPropagation()">';h+='<button class="tbl-btn view-btn" onclick="enterGaleriDetail(\''+escJS(g.folder)+'\',\''+escJS(g.album)+'\')"><svg viewBox="0 0 24 24"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg></button>';h+='<button class="tbl-btn del" onclick="deleteGroupG(\''+escJS(g.folder)+'\',\''+escJS(g.album)+'\')"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>';h+='</div></td></tr>';}h+='</tbody></table>';wrap.innerHTML=h;if(mode==='preview'&&gr.length>5)footer.innerHTML='<div class="show-more-bar"><button class="show-more-btn" onclick="enterGaleriFull()">Lihat Selengkapnya</button></div>';else if(mode==='full')footer.innerHTML=buildPgHTML(galeriPage,tp,gr.length,s+1,e,'goGaleriPage','setGaleriPageSize',galeriPageSize);else footer.innerHTML='';}else if(mode==='detail'){var cf=galeriCurrentFolder;var ph=getPhotosInFolder(cf.folder,cf.album,sv);if(!ph.length){wrap.innerHTML='<div style="padding:40px;text-align:center;color:var(--muted)">Tidak ditemukan</div>';footer.innerHTML='';return;}var tp=Math.max(1,Math.ceil(ph.length/galeriPageSize));if(galeriPage>tp)galeriPage=tp;var s=(galeriPage-1)*galeriPageSize,e=Math.min(s+galeriPageSize,ph.length),sh=ph.slice(s,e);var h='<table class="gal-table"><thead><tr><th>No</th><th>Preview</th><th>Alt</th><th>Path</th><th>Aksi</th></tr></thead><tbody>';for(var i=0;i<sh.length;i++){var r=sh[i];h+='<tr><td style="color:var(--muted)">'+(s+i+1)+'</td><td><img class="thumb" src="'+escAttr(r.src)+'" onerror="this.style.display=\'none\'"></td><td>'+escHtml(r.alt||'-')+'</td><td class="src-cell">'+escHtml(r.src)+'</td><td><div class="table-actions">';h+='<button class="tbl-btn" onclick="openEditG(\''+r.id+'\')"><svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>';h+='<button class="tbl-btn del" onclick="openDeleteG(\''+r.id+'\')"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>';h+='</div></td></tr>';}h+='</tbody></table>';wrap.innerHTML=h;footer.innerHTML=buildPgHTML(galeriPage,tp,ph.length,s+1,e,'goGaleriPage','setGaleriPageSize',galeriPageSize);}}
function goGaleriPage(p){var mx;if(galeriMode==='full')mx=Math.max(1,Math.ceil(getFolderGroups('').length/galeriPageSize));else if(galeriMode==='detail'){var cf=galeriCurrentFolder;mx=Math.max(1,Math.ceil(getPhotosInFolder(cf.folder,cf.album,'').length/galeriPageSize));}else return;if(p<1||p>mx)return;galeriPage=p;renderGaleriTable();}
function setGaleriPageSize(v){galeriPageSize=v;galeriPage=1;renderGaleriTable();}
function addGaleri(){var btn=document.getElementById('addGBtn');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var val=ddState.g.value,fo,al,la;if(val==='__new__'||!val){fo=document.getElementById('gCat').value;al=ddState.g.newKey.trim();la=document.getElementById('gLabel').value.trim();if(!al){toast('Ketik nama folder','error');btn.disabled=false;btn.textContent='Tambah';return;}}else{var pts=val.split(':::');fo=pts[0];al=pts[1];la=document.getElementById('gLabel').value.trim();}var st=document.getElementById('gSrc').value.trim(),at=document.getElementById('gAlt').value.trim();if(!st){toast('Path wajib','error');btn.disabled=false;btn.textContent='Tambah';return;}var fns=st.split(/[\n,]+/).map(function(f){return f.trim();}).filter(function(f){return f!=='';});var sb=currentBasePath;var chain=Promise.resolve();var hasErr=false;fns.forEach(function(fn){var fp=sb?sb+fn:fn;chain=chain.then(function(){return apiPost({action:'addGallery',folder:fo,album:al,label:la,src:fp,alt:at}).catch(function(){hasErr=true;return null;});});});chain.then(function(){if(!hasErr)toast('Berhasil','success');else toast('Ada yg gagal','error');if(document.getElementById('quickG').checked){galeriMode='preview';galeriPage=1;refreshGaleri();}else{resetGForm();galeriMode='preview';galeriPage=1;refreshGaleri();}}).finally(function(){btn.disabled=false;btn.textContent='Tambah';});}
function resetGForm(){document.getElementById('gCat').value='lana';ddState.g.value='';ddState.g.newKey='';document.getElementById('gAlbumSearch').value='';closeAlbumDD('g');lockField(document.getElementById('gLabel'));setLockedField(document.getElementById('gLabel'),'');lockField(document.getElementById('gAlt'));setLockedField(document.getElementById('gAlt'),'');document.getElementById('gSrc').value='';document.getElementById('gBasePathWrap').style.display='none';document.getElementById('gRangeWrap').style.display='none';currentBasePath='';}
function openEditG(id){var r=galeriData.find(function(x){return x.id===id;});if(!r)return;editingGId=id;document.getElementById('egCat').value=r.folder;var cv=r.folder+':::'+r.album;ddState.eg.value=cv;ddState.eg.newKey='';var f=findFolder(cv);document.getElementById('egAlbumSearch').value=f?f.name:(r.label||r.album);lockField(document.getElementById('egLabel'));lockField(document.getElementById('egAlt'));setLockedField(document.getElementById('egLabel'),r.label||'');setLockedField(document.getElementById('egAlt'),r.alt||'');document.getElementById('egSrc').value=r.src;if(f&&f.dir){document.getElementById('egBasePathWrap').style.display='';document.getElementById('egBasePathText').textContent=f.dir;}else document.getElementById('egBasePathWrap').style.display='none';openModal('editGModal');}
function saveEditG(){var btn=document.querySelector('#editGModal .btn-save');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var val=ddState.eg.value,fo,al,la;if(val==='__new__'||!val){fo=document.getElementById('egCat').value;al=ddState.eg.newKey.trim();la=document.getElementById('egLabel').value.trim();if(!al){toast('Ketik nama folder','error');btn.disabled=false;btn.textContent='Simpan';return;}}else{var pts=val.split(':::');fo=pts[0];al=pts[1];la=document.getElementById('egLabel').value.trim();}var sr=document.getElementById('egSrc').value.trim(),at=document.getElementById('egAlt').value.trim();if(!al||!sr){toast('Album dan path wajib','error');btn.disabled=false;btn.textContent='Simpan';return;}apiPost({action:'editGallery',id:editingGId,folder:fo,album:al,label:la,src:sr,alt:at}).then(function(r){if(r.success){toast('Diupdate','success');closeModal('editGModal');refreshGaleri();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Simpan';});}
function openDeleteG(id){document.getElementById('deleteMsg').innerHTML='Hapus foto ini?';var btn=document.getElementById('deleteConfirmBtn');btn.textContent='Hapus';btn.className='btn-confirm';btn.disabled=false;btn.onclick=function(){if(btn.disabled)return;btn.disabled=true;btn.textContent='Menghapus...';apiPost({action:'deleteGallery',id:id}).then(function(r){if(r.success){toast('Dihapus','success');closeModal('deleteModal');refreshGaleri();}else{toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';}}).catch(function(){toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';});};openModal('deleteModal');}
function deleteGroupG(folder,album){var c=galeriData.filter(function(r){return r.folder===folder&&r.album===album;}).length;document.getElementById('deleteMsg').innerHTML='Hapus <strong style="color:var(--red)">'+c+' foto</strong> dari album ini?';var btn=document.getElementById('deleteConfirmBtn');btn.textContent='Hapus Semua';btn.className='btn-confirm';btn.disabled=false;btn.onclick=function(){if(btn.disabled)return;btn.disabled=true;btn.textContent='Menghapus...';apiPost({action:'deleteGalleryGroup',folder:folder,album:album}).then(function(r){if(r.success){toast(r.deleted+' foto dihapus','success');closeModal('deleteModal');galeriPage=1;refreshGaleri();}else{toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus Semua';}}).catch(function(){toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus Semua';});};openModal('deleteModal');}

/* ===== HASHTAG CRUD ===== */
function refreshHashtag(){document.getElementById('hashtagBody').innerHTML='<tr class="empty-row"><td colspan="4"><div class="spinner"></div><br>Memuat...</td></tr>';apiGet('readHashtags').then(function(d){hashtagData=d||[];document.getElementById('hStatTotal').textContent=hashtagData.length;document.getElementById('hStatDesc').textContent=hashtagData.filter(function(r){return r.keterangan;}).length;hashtagMode='preview';hashtagPage=1;applyHashtagView();updateDashboardCounts();}).catch(function(){hashtagData=[];document.getElementById('hashtagBody').innerHTML='<tr class="empty-row"><td colspan="4" style="color:var(--red)">Gagal memuat</td></tr>';});}
function getFilteredHashtags(){var s=(document.getElementById('searchH').value||'').toLowerCase();return hashtagData.filter(function(r){return!s||r.hashtag.toLowerCase().indexOf(s)!==-1||(r.keterangan||'').toLowerCase().indexOf(s)!==-1;});}
function applyHashtagView(){var isF=hashtagMode==='full';document.getElementById('hashtagHome').classList.toggle('j-hide',isF);document.getElementById('hashtagBack').classList.toggle('j-hide',!isF);renderHashtagTable();}
function renderHashtagTable(){var f=getFilteredHashtags(),isS=!!(document.getElementById('searchH').value||'').trim();if(isS&&hashtagMode==='preview')hashtagMode='full';if(!f.length){document.getElementById('hashtagBody').innerHTML='<tr class="empty-row"><td colspan="4">'+(isS?'Tidak ditemukan':'Belum ada data')+'</td></tr>';document.getElementById('hashtagFooter').innerHTML='';return;}if(hashtagMode==='preview'){document.getElementById('hashtagBody').innerHTML=buildHRows(f.slice(0,5),1);document.getElementById('hashtagFooter').innerHTML=f.length>5?'<div class="show-more-bar"><button class="show-more-btn" onclick="enterHashtagFull()">Lihat Selengkapnya</button></div>':'';}else{var tp=Math.max(1,Math.ceil(f.length/hashtagPageSize));if(hashtagPage>tp)hashtagPage=tp;var s=(hashtagPage-1)*hashtagPageSize,e=Math.min(s+hashtagPageSize,f.length);document.getElementById('hashtagBody').innerHTML=buildHRows(f.slice(s,e),s+1);document.getElementById('hashtagFooter').innerHTML=buildPgHTML(hashtagPage,tp,f.length,s+1,e,'goHashtagPage','setHashtagPageSize',hashtagPageSize);}}
function cleanHashtag(tag){tag=tag.trim();while(tag.startsWith('#'))tag=tag.substring(1);return tag.trim();}
function buildHRows(items,no){var h='';for(var i=0;i<items.length;i++){var r=items[i];h+='<tr><td style="color:var(--muted)">'+(no+i)+'</td><td><span class="hashtag-text">#'+escHtml(r.hashtag)+'</span></td><td style="font-size:.8rem;color:var(--muted)">'+escHtml(r.keterangan||'-')+'</td><td><div class="table-actions"><button class="tbl-btn" onclick="openEditH(\''+r.id+'\')"><svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="tbl-btn del" onclick="openDeleteH(\''+r.id+'\')"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button></div></td></tr>';}return h;}
function enterHashtagFull(){hashtagMode='full';hashtagPage=1;applyHashtagView();}
function exitHashtagFull(){hashtagMode='preview';document.getElementById('searchH').value='';applyHashtagView();}
function onHashtagSearch(){var isS=!!(document.getElementById('searchH').value||'').trim();if(isS&&hashtagMode==='preview'){hashtagMode='full';applyHashtagView();}else renderHashtagTable();}
function goHashtagPage(p){var f=getFilteredHashtags();if(p<1||p>Math.max(1,Math.ceil(f.length/hashtagPageSize)))return;hashtagPage=p;renderHashtagTable();}
function setHashtagPageSize(v){hashtagPageSize=v;hashtagPage=1;renderHashtagTable();}
function addHashtag(){var btn=document.getElementById('addHBtn');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var tag=cleanHashtag(document.getElementById('hTag').value),ket=document.getElementById('hDesk').value.trim();if(!tag){toast('Hashtag wajib diisi','error');btn.disabled=false;btn.textContent='Tambah';return;}apiPost({action:'addHashtag',hashtag:tag,keterangan:ket}).then(function(r){if(r.success){toast('Hashtag ditambahkan','success');if(document.getElementById('quickH').checked){document.getElementById('hTag').value='';document.getElementById('hDesk').value='';}else resetHForm();hashtagMode='preview';refreshHashtag();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Tambah';});}
function resetHForm(){document.getElementById('hTag').value='';document.getElementById('hDesk').value='';}
function openEditH(id){var r=hashtagData.find(function(x){return x.id===id;});if(!r)return;editingHId=id;document.getElementById('ehTag').value=r.hashtag.replace(/^#/,'');document.getElementById('ehDesk').value=r.keterangan||'';openModal('editHModal');}
function saveEditH(){var btn=document.querySelector('#editHModal .btn-save');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var tag=cleanHashtag(document.getElementById('ehTag').value),ket=document.getElementById('ehDesk').value.trim();if(!tag){toast('Hashtag wajib diisi','error');btn.disabled=false;btn.textContent='Simpan';return;}apiPost({action:'editHashtag',id:editingHId,hashtag:tag,keterangan:ket}).then(function(r){if(r.success){toast('Hashtag diupdate','success');closeModal('editHModal');refreshHashtag();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Simpan';});}
function openDeleteH(id){var r=hashtagData.find(function(x){return x.id===id;});document.getElementById('deleteMsg').innerHTML='Hapus hashtag "<strong style="color:var(--text)">#'+escHtml(r?r.hashtag:'')+'</strong>"?';var btn=document.getElementById('deleteConfirmBtn');btn.textContent='Hapus';btn.className='btn-confirm';btn.disabled=false;btn.onclick=function(){if(btn.disabled)return;btn.disabled=true;btn.textContent='Menghapus...';apiPost({action:'deleteHashtag',id:id}).then(function(r){if(r.success){toast('Hashtag dihapus','success');closeModal('deleteModal');refreshHashtag();}else{toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';}}).catch(function(){toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';});};openModal('deleteModal');}

/* ===== ARTIKEL CRUD ===== */
function refreshArtikel(){
  document.getElementById('artikelBody').innerHTML='<tr class="empty-row"><td colspan="6"><div class="spinner"></div><br>Memuat...</td></tr>';
  document.getElementById('artikelFooter').innerHTML='';
  apiGet('readArticles').then(function(d){
    if(!Array.isArray(d)){
      artikelData=[];var errMsg=d&&d.error?d.error:'Respon tidak valid';
      document.getElementById('artikelBody').innerHTML='<tr class="empty-row"><td colspan="6" style="color:var(--red)">Gagal memuat: '+escHtml(errMsg)+'<br><small style="color:var(--muted)">Pastikan script sudah dideploy ulang dan setup() sudah dijalankan</small></td></tr>';
      document.getElementById('aStatTotal').textContent='0';document.getElementById('aStatBulan').textContent='0';artikelMode='preview';applyArtikelView();updateDashboardCounts();return;
    }
    artikelData=d;document.getElementById('aStatTotal').textContent=artikelData.length;
    var now=new Date(),bm=0;artikelData.forEach(function(r){var dt=parseIDDate(r.tanggal);if(dt){var dd=new Date(dt);if(dd.getMonth()===now.getMonth()&&dd.getFullYear()===now.getFullYear())bm++;}});
    document.getElementById('aStatBulan').textContent=bm;artikelMode='preview';artikelPage=1;applyArtikelView();updateDashboardCounts();
  }).catch(function(e){artikelData=[];document.getElementById('artikelBody').innerHTML='<tr class="empty-row"><td colspan="6" style="color:var(--red)">Gagal memuat<br><small style="color:var(--muted)">Periksa koneksi internet dan pastikan URL API sudah benar</small></td></tr>';document.getElementById('aStatTotal').textContent='0';document.getElementById('aStatBulan').textContent='0';artikelMode='preview';applyArtikelView();updateDashboardCounts();});
}
function getFilteredArtikel(){var s=(document.getElementById('searchA').value||'').toLowerCase();return artikelData.filter(function(r){return!s||r.judul.toLowerCase().indexOf(s)!==-1||(r.penulis||'').toLowerCase().indexOf(s)!==-1||(r.tanggal||'').toLowerCase().indexOf(s)!==-1;});}
function applyArtikelView(){var isF=artikelMode==='full';document.getElementById('artikelHome').classList.toggle('j-hide',isF);document.getElementById('artikelBack').classList.toggle('j-hide',!isF);renderArtikelTable();}
function renderArtikelTable(){var f=getFilteredArtikel(),isS=!!(document.getElementById('searchA').value||'').trim();if(isS&&artikelMode==='preview')artikelMode='full';if(!f.length){document.getElementById('artikelBody').innerHTML='<tr class="empty-row"><td colspan="6">'+(isS?'Tidak ditemukan':'Belum ada artikel')+'</td></tr>';document.getElementById('artikelFooter').innerHTML='';return;}if(artikelMode==='preview'){document.getElementById('artikelBody').innerHTML=buildARows(f.slice(0,5),1);document.getElementById('artikelFooter').innerHTML=f.length>5?'<div class="show-more-bar"><button class="show-more-btn" onclick="enterArtikelFull()">Lihat Selengkapnya</button></div>':'';}else{var tp=Math.max(1,Math.ceil(f.length/artikelPageSize));if(artikelPage>tp)artikelPage=tp;var s=(artikelPage-1)*artikelPageSize,e=Math.min(s+artikelPageSize,f.length);document.getElementById('artikelBody').innerHTML=buildARows(f.slice(s,e),s+1);document.getElementById('artikelFooter').innerHTML=buildPgHTML(artikelPage,tp,f.length,s+1,e,'goArtikelPage','setArtikelPageSize',artikelPageSize);}}
function buildARows(items,no){var h='';for(var i=0;i<items.length;i++){var r=items[i];var fotoHtml=r.foto?'<img class="artikel-thumb" src="'+escAttr(r.foto)+'" onerror="this.outerHTML=\'<span style=color:var(--muted);font-size:.72rem>error</span>\'">':'<span style="color:var(--muted);font-size:.72rem">-</span>';var kontenSnippet=r.konten?(r.konten.length>60?escHtml(r.konten.substring(0,60))+'...':escHtml(r.konten)):'';h+='<tr><td style="color:var(--muted)">'+(no+i)+'</td><td>'+fotoHtml+'</td><td><div style="font-weight:500">'+escHtml(r.judul)+'</div>'+(kontenSnippet?'<div style="font-size:.72rem;color:var(--muted);margin-top:2px">'+kontenSnippet+'</div>':'')+'</td><td>'+escHtml(r.tanggal)+'</td><td><span class="penulis-text">'+escHtml(r.penulis||'-')+'</span></td><td><div class="table-actions">';h+='<button class="tbl-btn" onclick="openEditA(\''+r.id+'\')" title="Edit"><svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>';h+='<button class="tbl-btn del" onclick="openDeleteA(\''+r.id+'\')" title="Hapus"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>';h+='</div></td></tr>';}return h;}
function enterArtikelFull(){artikelMode='full';artikelPage=1;applyArtikelView();}
function exitArtikelFull(){artikelMode='preview';document.getElementById('searchA').value='';applyArtikelView();}
function onArtikelSearch(){var isS=!!(document.getElementById('searchA').value||'').trim();if(isS&&artikelMode==='preview'){artikelMode='full';applyArtikelView();}else renderArtikelTable();}
function goArtikelPage(p){var f=getFilteredArtikel();if(p<1||p>Math.max(1,Math.ceil(f.length/artikelPageSize)))return;artikelPage=p;renderArtikelTable();}
function setArtikelPageSize(v){artikelPageSize=v;artikelPage=1;renderArtikelTable();}
function resetAForm(){document.getElementById('aJudul').value='';document.getElementById('aKonten').value='';document.getElementById('aTanggal').value=(function(){var t=new Date();return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');})();document.getElementById('aPenulis').value='';artikelFotoBase64='';removeFoto(null,'add');}
function addArtikel(){var btn=document.getElementById('addABtn');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var judul=document.getElementById('aJudul').value.trim();var konten=document.getElementById('aKonten').value.trim();var tgl=document.getElementById('aTanggal').value;var penulis=document.getElementById('aPenulis').value.trim();if(!judul||!tgl){toast('Judul dan tanggal wajib diisi','error');btn.disabled=false;btn.textContent='Tambah';return;}apiPost({action:'addArticle',judul:judul,konten:konten,tanggal:toIDDate(tgl),penulis:penulis,foto:artikelFotoBase64}).then(function(r){if(r.success){toast('Artikel ditambahkan','success');if(document.getElementById('quickA').checked){document.getElementById('aJudul').value='';document.getElementById('aKonten').value='';document.getElementById('aTanggal').value=(function(){var t=new Date();return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');})();document.getElementById('aPenulis').value='';artikelFotoBase64='';removeFoto(null,'add');}else resetAForm();artikelMode='preview';refreshArtikel();}else toast('Gagal menambahkan','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Tambah';});}
function openEditA(id){var r=artikelData.find(function(x){return x.id===id;});if(!r)return;editingAId=id;document.getElementById('eaJudul').value=r.judul||'';document.getElementById('eaKonten').value=r.konten||'';document.getElementById('eaTanggal').value=fromIDDate(r.tanggal||'');document.getElementById('eaPenulis').value=r.penulis||'';editArtikelFotoOriginal=r.foto||'';editArtikelFotoBase64='';if(r.foto){showFotoPreview('ea',r.foto);}else{removeFoto(null,'edit');}openModal('editAModal');}
function saveEditA(){var btn=document.querySelector('#editAModal .btn-save');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var judul=document.getElementById('eaJudul').value.trim();var konten=document.getElementById('eaKonten').value.trim();var tgl=document.getElementById('eaTanggal').value;var penulis=document.getElementById('eaPenulis').value.trim();if(!judul||!tgl){toast('Judul dan tanggal wajib','error');btn.disabled=false;btn.textContent='Simpan';return;}var foto=editArtikelFotoBase64||editArtikelFotoOriginal||'';apiPost({action:'editArticle',id:editingAId,judul:judul,konten:konten,tanggal:toIDDate(tgl),penulis:penulis,foto:foto}).then(function(r){if(r.success){toast('Artikel diupdate','success');closeModal('editAModal');refreshArtikel();}else toast('Gagal update','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Simpan';});}
function openDeleteA(id){var r=artikelData.find(function(x){return x.id===id;});document.getElementById('deleteMsg').innerHTML='Hapus artikel "<strong style="color:var(--text)">'+escHtml(r?r.judul:'')+'</strong>"?';var btn=document.getElementById('deleteConfirmBtn');btn.textContent='Hapus';btn.className='btn-confirm';btn.disabled=false;btn.onclick=function(){if(btn.disabled)return;btn.disabled=true;btn.textContent='Menghapus...';apiPost({action:'deleteArticle',id:id}).then(function(r){if(r.success){toast('Artikel dihapus','success');closeModal('deleteModal');refreshArtikel();}else{toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';}}).catch(function(){toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';});};openModal('deleteModal');}

/* ===== QUIZ CRUD ===== */
function refreshQuiz(){
  var qBody=document.getElementById('quizBody');
  if(qBody)qBody.innerHTML='<tr class="empty-row"><td colspan="8"><div class="spinner"></div><br>Memuat...</td></tr>';
  var qFooter=document.getElementById('quizFooter');
  if(qFooter)qFooter.innerHTML='';
  apiGet('readQuizzes').then(function(d){
    if(!Array.isArray(d)){quizData=[];if(qBody)qBody.innerHTML='<tr class="empty-row"><td colspan="8" style="color:var(--red)">Gagal memuat</td></tr>';return;}
    quizData=d;
    var qStatTotal=document.getElementById('qStatTotal');if(qStatTotal)qStatTotal.textContent=quizData.length;
    quizMode='preview';quizPage=1;applyQuizView();updateDashboardCounts();
  }).catch(function(){quizData=[];if(qBody)qBody.innerHTML='<tr class="empty-row"><td colspan="8" style="color:var(--red)">Gagal memuat</td></tr>';});
}
function getFilteredQuiz(){var s=(document.getElementById('searchQ').value||'').toLowerCase();return quizData.filter(function(r){return!s||r.pertanyaan.toLowerCase().indexOf(s)!==-1;});}
function applyQuizView(){var isF=quizMode==='full';var qHome=document.getElementById('quizHome');if(qHome)qHome.classList.toggle('j-hide',isF);var qBack=document.getElementById('quizBack');if(qBack)qBack.classList.toggle('j-hide',!isF);renderQuizTable();}
function renderQuizTable(){var f=getFilteredQuiz(),isS=!!(document.getElementById('searchQ').value||'').trim();if(isS&&quizMode==='preview')quizMode='full';if(!f.length){var qBody=document.getElementById('quizBody');if(qBody)qBody.innerHTML='<tr class="empty-row"><td colspan="8">'+(isS?'Tidak ditemukan':'Belum ada soal')+'</td></tr>';var qFooter=document.getElementById('quizFooter');if(qFooter)qFooter.innerHTML='';return;}if(quizMode==='preview'){var qBody=document.getElementById('quizBody');if(qBody)qBody.innerHTML=buildQRows(f.slice(0,5),1);var qFooter=document.getElementById('quizFooter');if(qFooter)qFooter.innerHTML=f.length>5?'<div class="show-more-bar"><button class="show-more-btn" onclick="enterQuizFull()">Lihat Selengkapnya</button></div>':'';}else{var tp=Math.max(1,Math.ceil(f.length/quizPageSize));if(quizPage>tp)quizPage=tp;var s=(quizPage-1)*quizPageSize,e=Math.min(s+quizPageSize,f.length);var qBody=document.getElementById('quizBody');if(qBody)qBody.innerHTML=buildQRows(f.slice(s,e),s+1);var qFooter=document.getElementById('quizFooter');if(qFooter)qFooter.innerHTML=buildPgHTML(quizPage,tp,f.length,s+1,e,'goQuizPage','setQuizPageSize',quizPageSize);}}
function buildQRows(items,no){var h='';for(var i=0;i<items.length;i++){var r=items[i];h+='<tr><td style="color:var(--muted)">'+(no+i)+'</td><td style="font-weight:500;max-width:250px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escHtml(r.pertanyaan)+'</td><td>'+escHtml(r.opsiA)+'</td><td>'+escHtml(r.opsiB)+'</td><td>'+escHtml(r.opsiC||'-')+'</td><td>'+escHtml(r.opsiD||'-')+'</td><td><span style="font-weight:700;color:var(--lime)">'+escHtml(r.jawaban)+'</span></td><td><div class="table-actions"><button class="tbl-btn" onclick="openEditQ(\''+r.id+'\')" title="Edit"><svg viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button class="tbl-btn del" onclick="openDeleteQ(\''+r.id+'\')" title="Hapus"><svg viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button></div></td></tr>';}return h;}
function enterQuizFull(){quizMode='full';quizPage=1;applyQuizView();}
function exitQuizFull(){quizMode='preview';document.getElementById('searchQ').value='';applyQuizView();}
function onQuizSearch(){var isS=!!(document.getElementById('searchQ').value||'').trim();if(isS&&quizMode==='preview'){quizMode='full';applyQuizView();}else renderQuizTable();}
function goQuizPage(p){var f=getFilteredQuiz();if(p<1||p>Math.max(1,Math.ceil(f.length/quizPageSize)))return;quizPage=p;renderQuizTable();}
function setQuizPageSize(v){quizPageSize=v;quizPage=1;renderQuizTable();}
function resetQForm(){document.getElementById('qPertanyaan').value='';document.getElementById('qOpsiA').value='';document.getElementById('qOpsiB').value='';document.getElementById('qOpsiC').value='';document.getElementById('qOpsiD').value='';document.getElementById('qJawaban').value='A';}
function addQuiz(){var btn=document.getElementById('addQBtn');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var pt=document.getElementById('qPertanyaan').value.trim(),a=document.getElementById('qOpsiA').value.trim(),b=document.getElementById('qOpsiB').value.trim(),c=document.getElementById('qOpsiC').value.trim(),d=document.getElementById('qOpsiD').value.trim(),j=document.getElementById('qJawaban').value;if(!pt||!a||!b){toast('Pertanyaan, Opsi A, dan B wajib diisi','error');btn.disabled=false;btn.textContent='Tambah';return;}apiPost({action:'addQuiz',pertanyaan:pt,opsiA:a,opsiB:b,opsiC:c,opsiD:d,jawaban:j}).then(function(r){if(r.success){toast('Quiz ditambahkan','success');if(document.getElementById('quickQ').checked)resetQForm();else resetQForm();quizMode='preview';refreshQuiz();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Tambah';});}
function openEditQ(id){var r=quizData.find(function(x){return x.id===id;});if(!r)return;editingQId=id;document.getElementById('eqPertanyaan').value=r.pertanyaan||'';document.getElementById('eqOpsiA').value=r.opsiA||'';document.getElementById('eqOpsiB').value=r.opsiB||'';document.getElementById('eqOpsiC').value=r.opsiC||'';document.getElementById('eqOpsiD').value=r.opsiD||'';document.getElementById('eqJawaban').value=r.jawaban||'A';openModal('editQModal');}
function saveEditQ(){var btn=document.querySelector('#editQModal .btn-save');if(btn.disabled)return;btn.disabled=true;btn.textContent='Menyimpan...';var pt=document.getElementById('eqPertanyaan').value.trim(),a=document.getElementById('eqOpsiA').value.trim(),b=document.getElementById('eqOpsiB').value.trim(),c=document.getElementById('eqOpsiC').value.trim(),d=document.getElementById('eqOpsiD').value.trim(),j=document.getElementById('eqJawaban').value;if(!pt||!a||!b){toast('Pertanyaan, Opsi A, dan B wajib','error');btn.disabled=false;btn.textContent='Simpan';return;}apiPost({action:'editQuiz',id:editingQId,pertanyaan:pt,opsiA:a,opsiB:b,opsiC:c,opsiD:d,jawaban:j}).then(function(r){if(r.success){toast('Quiz diupdate','success');closeModal('editQModal');refreshQuiz();}else toast('Gagal','error');}).catch(function(){toast('Gagal','error');}).finally(function(){btn.disabled=false;btn.textContent='Simpan';});}
function openDeleteQ(id){var r=quizData.find(function(x){return x.id===id;});document.getElementById('deleteMsg').innerHTML='Hapus soal quiz ini?';var btn=document.getElementById('deleteConfirmBtn');btn.textContent='Hapus';btn.className='btn-confirm';btn.disabled=false;btn.onclick=function(){if(btn.disabled)return;btn.disabled=true;btn.textContent='Menghapus...';apiPost({action:'deleteQuiz',id:id}).then(function(r){if(r.success){toast('Quiz dihapus','success');closeModal('deleteModal');refreshQuiz();}else{toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';}}).catch(function(){toast('Gagal','error');btn.disabled=false;btn.textContent='Hapus';});};openModal('deleteModal');}

/* ===== PAGINATION ===== */
function buildPgHTML(c,t,tot,s,e,pFn,sFn,ps){if(!tot)return'';var h='<div class="pagination-bar"><div class="pagination-info">Menampilkan <strong>'+s+'-'+e+'</strong> dari <strong>'+tot+'</strong></div><div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap"><div style="display:flex;align-items:center;gap:6px;font-size:.76rem;color:var(--muted)">Tampil:<select class="pg-size-select" onchange="'+sFn+'(parseInt(this.value))">';[10,15,25,50].forEach(function(v){h+='<option value="'+v+'"'+(v===ps?' selected':'')+'>'+v+'</option>';});h+='</select></div><div class="pagination-controls"><button class="pg-btn" onclick="'+pFn+'('+(c-1)+')"'+(c<=1?' disabled':'')+'><svg viewBox="0 0 24 24"><polyline points="15 18 9 12 15 6"/></svg></button>';pgNums(c,t).forEach(function(p){if(p==='...')h+='<span class="pg-ellipsis">...</span>';else h+='<button class="pg-btn'+(p===c?' active':'')+'" onclick="'+pFn+'('+p+')">'+p+'</button>';});h+='<button class="pg-btn" onclick="'+pFn+'('+(c+1)+')"'+(c>=t?' disabled':'')+'><svg viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg></button></div></div></div>';return h;}
function pgNums(c,t){if(t<=7){var a=[];for(var i=1;i<=t;i++)a.push(i);return a;}var p=[1];if(c>3)p.push('...');for(var j=Math.max(2,c-1);j<=Math.min(t-1,c+1);j++)p.push(j);if(c<t-2)p.push('...');p.push(t);return p;}

/* ===== MODAL & TOAST ===== */
function openModal(id){document.getElementById(id).classList.add('active');}
function closeModal(id){document.getElementById(id).classList.remove('active');}
document.querySelectorAll('.modal-overlay').forEach(function(el){el.addEventListener('click',function(e){if(e.target===el)el.classList.remove('active');});});
var toastTimers={};
function toast(msg,type){var key=msg+'|'+type;if(toastTimers[key])return;toastTimers[key]=true;setTimeout(function(){delete toastTimers[key];},4000);var t=document.createElement('div');t.className='toast '+(type||'info');t.textContent=msg;document.getElementById('toastBox').appendChild(t);setTimeout(function(){t.classList.add('show');},30);setTimeout(function(){t.classList.remove('show');setTimeout(function(){t.remove();},400);},3500);}

/* ===== ENFORCE LOCKED FIELDS ===== */
(function(){var ids=['gLabel','gAlt','egLabel','egAlt'];function enforceLock(){ids.forEach(function(id){var el=document.getElementById(id);if(!el)return;if(el.classList.contains('locked')){el.setAttribute('readonly','');el.setAttribute('tabindex','-1');el.style.pointerEvents='none';el.style.userSelect='none';el.style.webkitUserSelect='none';}else{el.removeAttribute('readonly');el.removeAttribute('tabindex');el.style.pointerEvents='';el.style.userSelect='';el.style.webkitUserSelect='';}});}enforceLock();setInterval(enforceLock,500);})();

